public class Scenario { public string Name="New scenario"; public bool Enabled=true; public int Modifiers=8; public int Key=123; public List<int> Chord=new List<int>(); public string Output=""; public string Input=""; public List<ScenarioFeature> Features; }
public enum FeatureType { Output, Input, PauseMedia, PlayMedia, NextMedia, PreviousMedia, MuteMedia, PlayPauseMedia }
public class ScenarioFeature {public FeatureType Type;public string DeviceId="";}
public static class Features {
 public static List<ScenarioFeature> For(Scenario s){if(s.Features!=null&&s.Features.Count>0)return s.Features;var list=new List<ScenarioFeature>();if(!String.IsNullOrEmpty(s.Output))list.Add(new ScenarioFeature{Type=FeatureType.Output,DeviceId=s.Output});if(!String.IsNullOrEmpty(s.Input))list.Add(new ScenarioFeature{Type=FeatureType.Input,DeviceId=s.Input});return list;}
 public static string Name(FeatureType type){switch(type){case FeatureType.Output:return "Output";case FeatureType.Input:return "Input";case FeatureType.PauseMedia:case FeatureType.PlayMedia:case FeatureType.PlayPauseMedia:return "Play/Pause";case FeatureType.NextMedia:return "Next media";case FeatureType.PreviousMedia:return "Prev media";case FeatureType.MuteMedia:return "Mute/Unmute";default:return "Unknown feature";}}
 public static bool IsDevice(FeatureType type){return type==FeatureType.Output||type==FeatureType.Input;}
}
public interface IFeatureBackend {List<Device> ListDevices(int flow);string GetDefault(int flow,int role);void SetDefault(string id,int role);void SendMedia(FeatureType type);void Mute();}
public class WindowsFeatureBackend:IFeatureBackend {
 public List<Device> ListDevices(int flow){return Audio.List(flow);}public string GetDefault(int flow,int role){return Audio.Default(flow,role);}public void SetDefault(string id,int role){Audio.Set(id,role);}public void SendMedia(FeatureType type){Media.Send(type);}public void Mute(){Audio.ToggleMuted();}
}
public static class FeatureRunner {
 public static void Run(Scenario scenario,IFeatureBackend backend){var features=Features.For(scenario);if(features.Count==0)throw new Exception("This scenario has no features. Edit it to add a feature.");foreach(var f in features)if(f==null||!Enum.IsDefined(typeof(FeatureType),f.Type))throw new Exception("This scenario contains an unsupported feature. Edit it before running.");
 var flows=features.Where(f=>Features.IsDevice(f.Type)).Select(f=>f.Type==FeatureType.Output?0:1).Distinct().ToList();var originals=new Dictionary<int,string[]>();foreach(int flow in flows){var available=backend.ListDevices(flow);if(features.Any(f=>Features.IsDevice(f.Type)&&(f.Type==FeatureType.Output?0:1)==flow&&!available.Any(d=>d.Id==f.DeviceId)))throw new Exception("A selected device is disconnected. Reconnect it or edit this scenario.");var ids=new string[3];for(int r=0;r<3;r++)try{ids[r]=backend.GetDefault(flow,r);}catch{}originals[flow]=ids;}
 bool deviceChanges=false,otherActions=false;try{foreach(var f in features){if(Features.IsDevice(f.Type)){deviceChanges=true;for(int r=0;r<3;r++)backend.SetDefault(f.DeviceId,r);}else{otherActions=true;if(f.Type==FeatureType.MuteMedia)backend.Mute();else backend.SendMedia(f.Type);}}}
 catch(Exception ex){bool restored=true;if(deviceChanges)foreach(var pair in originals)for(int r=0;r<3;r++)if(pair.Value[r]!=null)try{backend.SetDefault(pair.Value[r],r);}catch{restored=false;}
 throw new Exception("Scenario failed: "+ex.Message+(deviceChanges?(restored?" Previous audio defaults were restored.":" Check Windows sound settings; some defaults could not be restored."):"")+(otherActions?" Media actions already sent cannot be undone.":""),ex);}}
}
public static class Media {
 public static int Command(FeatureType type){switch(type){case FeatureType.PlayMedia:case FeatureType.PauseMedia:case FeatureType.PlayPauseMedia:return 14;case FeatureType.NextMedia:return 11;case FeatureType.PreviousMedia:return 12;default:throw new ArgumentException("Unsupported media command");}}
 public static void Send(FeatureType type){SendTo(GetShellWindow(),type);}
 public static void SendTo(IntPtr window,FeatureType type){if(window==IntPtr.Zero)throw new Exception("Windows media controls are unavailable.");IntPtr result;if(SendMessageTimeout(window,0x319,window,(IntPtr)(Command(type)<<16),2,1000,out result)==IntPtr.Zero)throw new Exception("Windows did not accept the media command.");}
