 [DllImport("user32.dll",SetLastError=true)]static extern IntPtr SendMessageTimeout(IntPtr window,uint msg,IntPtr w,IntPtr l,uint flags,uint timeout,out IntPtr result);
}
public static class SettingsFile {
 public static Settings Load(string path){var settings=new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=2097152};using(var stream=File.OpenRead(path)){if(stream.Length>2097152)throw new InvalidDataException("Settings file is too large.");using(var reader=XmlReader.Create(stream,settings)){var value=(Settings)new XmlSerializer(typeof(Settings)).Deserialize(reader);if(value==null)throw new InvalidDataException("Settings are empty.");if(value.Scenarios==null)value.Scenarios=new List<Scenario>();if(value.Scenarios.Count>1000||value.Scenarios.Any(s=>s==null||(s.Chord!=null&&s.Chord.Count>256)||(s.Features!=null&&s.Features.Count>1000)))throw new InvalidDataException("Settings contain too many items.");return value;}}}
}
