public static class Chords {
 public static int Normalize(int key){if(key==160||key==161)return 16;if(key==162||key==163)return 17;if(key==164||key==165)return 18;if(key==92)return 91;return key;}
 public static bool Modifier(int key){return key==16||key==17||key==18||key==91;}
 public static List<int> KeysFor(Scenario s){if(s.Chord!=null&&s.Chord.Count>0)return s.Chord.Select(Normalize).Distinct().ToList();var keys=new List<int>();if((s.Modifiers&8)!=0)keys.Add(91);if((s.Modifiers&2)!=0)keys.Add(17);if((s.Modifiers&1)!=0)keys.Add(18);if((s.Modifiers&4)!=0)keys.Add(16);keys.Add(s.Key);return keys.Distinct().ToList();}
 public static string Display(Scenario s){return String.Join(" + ",KeysFor(s).Select(Editor.KeyText));}
 public static bool Conflict(IEnumerable<int> a,IEnumerable<int> b){var x=new HashSet<int>(a.Select(Normalize));var y=new HashSet<int>(b.Select(Normalize));return x.IsSubsetOf(y)||y.IsSubsetOf(x);}
}
public class ChordTracker {
 HashSet<int> pressed=new HashSet<int>(),consumed=new HashSet<int>();
 public Func<HashSet<int>,bool> Trigger;
 public bool Process(int raw,bool down,IEnumerable<int> physical){int key=Chords.Normalize(raw);if(!down){pressed.Remove(key);return consumed.Remove(raw);}bool repeat=pressed.Contains(key);pressed=new HashSet<int>(physical.Select(Chords.Normalize));pressed.UnionWith(consumed.Select(Chords.Normalize));pressed.Add(key);if(consumed.Contains(raw))return true;if(repeat)return false;
 if(Trigger!=null&&Trigger(new HashSet<int>(pressed))){consumed.Add(raw);return true;}return false;}
}
