 public FeatureRow(ScenarioFeature feature,List<Device> outputDevices,List<Device> inputDevices){outputs=outputDevices;inputs=inputDevices;ColumnCount=3;RowCount=2;Height=70;Margin=new Padding(0,0,0,6);Padding=new Padding(8);BackColor=Theme.Card;ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,32));ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,94));RowStyles.Add(new RowStyle(SizeType.Absolute,26));RowStyles.Add(new RowStyle(SizeType.Absolute,26));DragHandle=ScenarioList.Grip();Controls.Add(DragHandle,0,0);SetRowSpan(DragHandle,2);TypeSelector=Theme.Combo();TypeSelector.Margin=new Padding(0,0,0,3);foreach(FeatureType type in new[]{FeatureType.Output,FeatureType.Input,FeatureType.PlayPauseMedia,FeatureType.NextMedia,FeatureType.PreviousMedia,FeatureType.MuteMedia})TypeSelector.Items.Add(new KeyItem{Value=(int)type,Name=Features.Name(type)});Controls.Add(TypeSelector,1,0);var remove=Theme.Button("Remove",delegate{if(RemoveRequested!=null)RemoveRequested(this,EventArgs.Empty);},false);remove.Dock=DockStyle.Fill;remove.Margin=new Padding(6,0,0,0);remove.Padding=new Padding(0);Controls.Add(remove,2,0);SetRowSpan(remove,2);DeviceSelector=Theme.Combo();Controls.Add(DeviceSelector,1,1);description=Theme.Label("Choose a feature above.",9,Theme.Muted);description.Dock=DockStyle.Fill;description.AutoSize=false;description.Margin=new Padding(0,2,0,0);Controls.Add(description,1,1);TypeSelector.SelectedIndexChanged+=delegate{UpdateTarget(null);};if(feature!=null){var type=feature.Type==FeatureType.PauseMedia||feature.Type==FeatureType.PlayMedia?FeatureType.PlayPauseMedia:feature.Type;for(int i=0;i<TypeSelector.Items.Count;i++)if(((KeyItem)TypeSelector.Items[i]).Value==(int)type)TypeSelector.SelectedIndex=i;UpdateTarget(feature.DeviceId);}else UpdateTarget(null);}
