public class ScenarioList:FlowLayoutPanel {
 bool sizing;public bool FixedPreferredHeight;int insertion=-1;static Control draggingRow;public event EventHandler OrderChanged;
 public ScenarioList(){AutoScroll=true;FlowDirection=FlowDirection.TopDown;WrapContents=false;Dock=DockStyle.Fill;DoubleBuffered=true;}
 public static Control Grip(){return new Label{Text="≡",Font=new Font("Segoe UI",18),ForeColor=Theme.Muted,TextAlign=ContentAlignment.MiddleCenter,Dock=DockStyle.Fill,Margin=new Padding(0),Cursor=Cursors.SizeAll,AccessibleName="Drag to reorder"};}
 public void AttachDragHandle(Control row,Control handle){AllowDrop=true;Point origin=Point.Empty;bool armed=false;handle.MouseDown+=delegate(object sender,MouseEventArgs e){armed=e.Button==MouseButtons.Left;origin=e.Location;};handle.MouseUp+=delegate{armed=false;};handle.MouseMove+=delegate(object sender,MouseEventArgs e){if(!armed||e.Button!=MouseButtons.Left)return;var threshold=new Rectangle(origin.X-SystemInformation.DragSize.Width/2,origin.Y-SystemInformation.DragSize.Height/2,SystemInformation.DragSize.Width,SystemInformation.DragSize.Height);if(threshold.Contains(e.Location))return;armed=false;try{draggingRow=row;handle.DoDragDrop("Makro Sound Switch row",DragDropEffects.Move);}finally{draggingRow=null;insertion=-1;Invalidate();}};}
 public void MoveRow(Control row,int index){if(row==null||row.Parent!=this)throw new ArgumentException("The row belongs to a different list");index=Math.Max(0,Math.Min(Controls.Count-1,index));if(Controls.GetChildIndex(row)==index)return;Controls.SetChildIndex(row,index);PerformLayout();if(OrderChanged!=null)OrderChanged(this,EventArgs.Empty);Invalidate();}
 Control Dragged(DragEventArgs e){return draggingRow!=null&&draggingRow.Parent==this?draggingRow:null;}
 int InsertionAt(Point point){for(int i=0;i<Controls.Count;i++)if(point.Y<Controls[i].Top+Controls[i].Height/2)return i;return Controls.Count;}
 protected override void OnDragEnter(DragEventArgs e){base.OnDragEnter(e);e.Effect=Dragged(e)==null?DragDropEffects.None:DragDropEffects.Move;}
 protected override void OnDragOver(DragEventArgs e){base.OnDragOver(e);if(Dragged(e)==null){e.Effect=DragDropEffects.None;return;}e.Effect=DragDropEffects.Move;ScrollableControl owner=AutoScroll?this:null;for(Control p=Parent;owner==null&&p!=null;p=p.Parent){var scrollable=p as ScrollableControl;if(scrollable!=null&&scrollable.AutoScroll)owner=scrollable;}if(owner!=null){var edge=owner.PointToClient(new Point(e.X,e.Y));int scroll=-owner.AutoScrollPosition.Y;if(edge.Y<28)owner.AutoScrollPosition=new Point(0,Math.Max(0,scroll-18));else if(edge.Y>owner.ClientSize.Height-28)owner.AutoScrollPosition=new Point(0,scroll+18);}var point=PointToClient(new Point(e.X,e.Y));insertion=InsertionAt(point);Invalidate();}
 protected override void OnDragLeave(EventArgs e){base.OnDragLeave(e);insertion=-1;Invalidate();}
 protected override void OnDragDrop(DragEventArgs e){base.OnDragDrop(e);var row=Dragged(e);if(row!=null){int target=InsertionAt(PointToClient(new Point(e.X,e.Y)));int old=Controls.GetChildIndex(row);if(target>old)target--;MoveRow(row,target);}insertion=-1;Invalidate();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(insertion<0||Controls.Count==0)return;int y=insertion<Controls.Count?Controls[insertion].Top-2:Controls[Controls.Count-1].Bottom+2;using(var pen=new Pen(Theme.Accent,3))e.Graphics.DrawLine(pen,0,y,ClientSize.Width-SystemInformation.VerticalScrollBarWidth-2,y);}
 public override Size GetPreferredSize(Size proposedSize){return new Size(0,FixedPreferredHeight?Height:0);}
 protected override void OnLayout(LayoutEventArgs e){if(sizing)return;sizing=true;try{int width=Math.Max(0,ClientSize.Width-Padding.Horizontal-(AutoScroll?SystemInformation.VerticalScrollBarWidth:0)-2);foreach(Control c in Controls)c.Width=Math.Max(0,width-c.Margin.Horizontal);base.OnLayout(e);}finally{sizing=false;}}
}
public static class StartupManager {
 const string RunKey="Software\\Microsoft\\Windows\\CurrentVersion\\Run";
 const string ValueName="MakroSoundSwitch";
 public static string Command(string executable){return "\""+executable+"\" --startup";}
 public static bool Enabled {get{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(RunKey)){return key!=null&&!String.IsNullOrEmpty(key.GetValue(ValueName) as string);}}}
 public static void SetEnabled(bool enabled){using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(RunKey)){if(enabled)key.SetValue(ValueName,Command(Application.ExecutablePath),Microsoft.Win32.RegistryValueKind.String);else key.DeleteValue(ValueName,false);}}
}
