 public MainForm(string configPath=null,bool forceShow=false,bool forceHidden=false){if(configPath!=null)config=configPath;Text="Makro Sound Switch V.0.1";Size=new Size(980,720);MinimumSize=new Size(800,560);BackColor=Theme.Bg;ForeColor=Theme.Text;Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterScreen;Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);
