 layout.Controls.Add(Theme.Label("Makro Sound Switch V.0.1",24,Theme.Text));layout.Controls.Add(Theme.Label("One shortcut. A whole new sound setup.",12,Theme.Muted));var toolbar=new FlowLayoutPanel{Dock=DockStyle.Fill};toolbar.Controls.Add(Theme.Button("+ New scenario",delegate{Edit(null);},true));toolbar.Controls.Add(Theme.Button("Refresh devices",delegate{RefreshDevices();Render();},false));var pause=Theme.Button("Pause shortcuts",null,false);pause.Click+=delegate{paused=!paused;pause.Text=paused?"Resume shortcuts":"Pause shortcuts";SetStatus(paused?"Shortcuts paused":"Shortcuts active");};toolbar.Controls.Add(pause);toolbar.Controls.Add(Theme.Button("Settings",delegate{OpenSettings();},false));layout.Controls.Add(toolbar);cards=new ScenarioList();layout.Controls.Add(cards);status=Theme.Label("Ready · Close the window to keep running in the tray.",10,Theme.Muted);status.Dock=DockStyle.Fill;status.Padding=new Padding(0,14,0,0);layout.Controls.Add(status);
 tray=new NotifyIcon{Icon=Icon,Text="Makro Sound Switch V.0.1",Visible=true};var menu=new ContextMenuStrip();menu.Items.Add("Open Makro Sound Switch V.0.1",null,delegate{ShowWindow();});menu.Items.Add("Exit",null,delegate{quitting=true;Close();});tray.ContextMenuStrip=menu;tray.DoubleClick+=delegate{ShowWindow();};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(!quitting&&e.CloseReason==CloseReason.UserClosing){if(data.CloseBehavior==CloseAction.Exit)return;e.Cancel=true;if(data.CloseBehavior==CloseAction.MinimizeToTaskbar){ShowInTaskbar=true;WindowState=FormWindowState.Minimized;}else{Hide();ShowInTaskbar=false;}}};
 try{if(File.Exists(config)){data=SettingsFile.Load(config);}}catch(Exception ex){SetStatus("Settings could not be loaded: "+ex.Message);MessageBox.Show("Your settings could not be loaded. The original file will be kept as a backup when saving.","Makro Sound Switch V.0.1");try{File.Copy(config,config+".unreadable-"+DateTime.Now.ToString("yyyyMMddHHmmss"));}catch{}}
