 foreach(var scenario in data.Scenarios){var s=scenario;var card=new TableLayoutPanel{Width=Math.Max(0,cards.ClientSize.Width-SystemInformation.VerticalScrollBarWidth-2),Height=182+Math.Max(0,Features.For(s).Count-2)*20,BackColor=Theme.Card,Padding=new Padding(20,12,20,12),Margin=new Padding(0,0,0,14),ColumnCount=2,RowCount=4};card.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));card.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,195));var title=Theme.Label(s.Name,18,Theme.Text);title.AutoSize=false;title.Margin=new Padding(0);title.AutoEllipsis=true;title.Dock=DockStyle.Fill;card.Controls.Add(title,0,0);var toggle=new CheckBox{Text=s.Enabled?"Enabled":"Disabled",Checked=s.Enabled,AutoSize=true,Dock=DockStyle.Right};toggle.CheckedChanged+=delegate{s.Enabled=toggle.Checked;toggle.Text=s.Enabled?"Enabled":"Disabled";Save();};card.Controls.Add(toggle,1,0);var shortcutLabel=Theme.Label(Chords.Display(s),11,Theme.Accent);shortcutLabel.AutoSize=false;shortcutLabel.AutoEllipsis=true;shortcutLabel.Dock=DockStyle.Fill;shortcutLabel.Margin=new Padding(0);card.Controls.Add(shortcutLabel,0,1);card.SetColumnSpan(shortcutLabel,2);var details=Theme.Label(String.Join("\n",Features.For(s).Select(f=>Features.Name(f.Type)+(Features.IsDevice(f.Type)?"   "+DeviceName(f.DeviceId):""))),10,Theme.Muted);details.AutoSize=false;details.Dock=DockStyle.Fill;details.AutoEllipsis=true;card.Controls.Add(details,0,2);card.SetColumnSpan(details,2);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};actions.Controls.Add(Theme.Button("Apply now",delegate{Apply(s);},true));actions.Controls.Add(Theme.Button("Edit",delegate{Edit(s);},false));actions.Controls.Add(Theme.Button("Delete",delegate{if(MessageBox.Show(this,"Delete '"+s.Name+"'?","Delete scenario",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){data.Scenarios.Remove(s);Save();Render();}},false));card.Controls.Add(actions,0,3);card.SetColumnSpan(actions,2);card.RowStyles.Add(new RowStyle(SizeType.Absolute,33));card.RowStyles.Add(new RowStyle(SizeType.Absolute,25));card.RowStyles.Add(new RowStyle(SizeType.Absolute,Math.Max(44,Features.For(s).Count*20+4)));card.RowStyles.Add(new RowStyle(SizeType.Absolute,42));cards.Controls.Add(card);}cards.ResumeLayout();}
 void Edit(Scenario s){editing=true;try{using(var e=new Editor(s,data.Scenarios)){if(e.ShowDialog(this)==DialogResult.OK){if(s==null)data.Scenarios.Add(e.Result);else data.Scenarios[data.Scenarios.IndexOf(s)]=e.Result;Save();RefreshDevices();Render();}}}finally{editing=false;}}
 void Save(){try{Directory.CreateDirectory(Path.GetDirectoryName(config));string temp=config+".tmp";using(var f=File.Create(temp))new XmlSerializer(typeof(Settings)).Serialize(f,data);if(File.Exists(config))File.Replace(temp,config,config+".bak");else File.Move(temp,config);}catch(Exception ex){MessageBox.Show(this,"Your change could not be saved: "+ex.Message,"Save failed",MessageBoxButtons.OK,MessageBoxIcon.Error);SetStatus("Save failed — changes are only in memory");}}
