}
static class Program {
 [STAThread]static void Main(string[] args){
 bool created;using(var mutex=new System.Threading.Mutex(true,"Local\\MakroSoundSwitch_App",out created)){if(!created){if(args.Contains("--startup"))return;try{using(var reopen=System.Threading.EventWaitHandle.OpenExisting("Local\\MakroSoundSwitch_Open"))reopen.Set();}catch{}return;}using(var reopen=new System.Threading.EventWaitHandle(false,System.Threading.EventResetMode.AutoReset,"Local\\MakroSoundSwitch_Open")){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var form=new MainForm(null,args.Contains("--show"),args.Contains("--startup"))){var registration=System.Threading.ThreadPool.RegisterWaitForSingleObject(reopen,delegate(object state,bool timedOut){try{form.BeginInvoke((Action)form.ShowWindow);}catch(InvalidOperationException){}},null,-1,false);try{Application.Run(form);}finally{registration.Unregister(null);}}}}}
}
